import { _decorator, sp } from 'cc';
import { SymbolView } from './SymbolView';
import { trySetAnimation, tryClearAnimation } from '../../utils/SpineSafe';

const { ccclass, property } = _decorator;

/**
 * Spine 版的顯示層：租出去時播一段動畫，回收時清掉軌道。
 *
 * 設計依據：entry repo `docs/SlotSymbolSystem_設計參考.md` §6（顯示技術轉接器）。
 * 邏輯層完全感覺不到自己租到的是 Sprite 版還是這一版。
 *
 * **比 1003 那份多了 {@link overlaySkeletons}。** 1001 的中獎演出是兩支 spine 疊著播：`symbol_h`／
 * `symbol_l` 畫符號本體（動畫名 = 圖名，例如 `symbol_l3`），`symbol_win` 在它上面畫火焰框
 * （動畫名一律 `animation`）。兩支的動畫名不同，單一 `skeleton` 欄位表達不了，所以主副分開：
 * 主 skeleton 決定「播完了沒」，副 skeleton 只是跟著一起播、一起停。
 */
@ccclass('1001/SymbolViewSpine')
export class SymbolViewSpine extends SymbolView {
    @property({ type: sp.Skeleton, tooltip: '實際播動畫的 Skeleton；留空時這顆物件等同靜態圖' })
    public skeleton: sp.Skeleton = null!;

    @property({
        tooltip: '租借時要播的動畫名稱。留空 = 不播任何動畫，只保留 setup pose 與 skin（倍率球的靜止態就是這樣）'
    })
    public animName: string = 'animation';

    @property({ tooltip: '是否循環播放。中獎中的常駐演出勾起來，一次性爆破不要勾' })
    public loop: boolean = false;

    @property({
        type: [sp.Skeleton],
        tooltip: '要跟著主 skeleton 一起播的疊加 spine（例如中獎的 symbol_win 火焰框），動畫名共用 overlayAnimName'
    })
    public overlaySkeletons: sp.Skeleton[] = [];

    @property({ tooltip: '疊加 spine 的動畫名稱' })
    public overlayAnimName: string = 'animation';

    @property({ tooltip: '疊加 spine 是否循環播放' })
    public overlayLoop: boolean = false;

    /**
     * 每個符號的動畫名稱可能不同（例如 `symbol_h` 這份骨架裡 h1 叫 `symbol_h1`、h2 叫 `symbol_h2`），
     * 所以租借時允許外部指定；沒指定就用 {@link animName}。
     */
    private overrideAnim: string | null = null;

    /**
     * 指定這次租借要播的動畫，必須在 {@link SymbolView.onRent} 之前呼叫。
     *
     * @param anim 動畫名稱；傳 null 表示改用 prefab 上設定的 {@link animName}。
     */
    public setAnimOverride(anim: string | null): void {
        this.overrideAnim = anim;
    }

    /** 這一次要播的主動畫名；空字串代表不播 */
    protected get currentAnim(): string {
        return this.overrideAnim ?? this.animName;
    }

    /** 建立當下先把軌道清乾淨，避免 prefab 存檔時殘留的預設動畫在節點一開就播出來 */
    protected override onInit(): void {
        if (this.skeleton) tryClearAnimation(this.skeleton, 'SymbolViewSpine.onInit');
        for (const overlay of this.overlaySkeletons) {
            if (overlay) tryClearAnimation(overlay, 'SymbolViewSpine.onInit(overlay)');
        }
    }

    /** 歸還：停掉動畫並清空軌道，否則下次租出去會先閃一格上一次的最後畫面 */
    public override onReturn(): void {
        if (this.skeleton?.isValid) {
            this.skeleton.setCompleteListener(null!);
            tryClearAnimation(this.skeleton, 'SymbolViewSpine.onReturn');
        }
        for (const overlay of this.overlaySkeletons) {
            if (overlay?.isValid) tryClearAnimation(overlay, 'SymbolViewSpine.onReturn(overlay)');
        }
        this.overrideAnim = null;
        super.onReturn();
    }

    /** 從頭重播。動畫名不存在時 {@link trySetAnimation} 會吞掉例外並警告一次，不會中斷整條流程 */
    public override resetAni(): void {
        this.playAll(this.loop, this.overlayLoop);
    }

    /**
     * 播一次並在結束時回呼。
     *
     * 只在 `trackIndex === 0` 時回呼，避免其他軌道的結束事件誤觸。沒有 skeleton、或這個狀態
     * 設定成不播動畫時立刻回呼，行為與基底一致。
     *
     * @param onComplete 播完時呼叫。
     */
    public override playOnce(onComplete: () => void): void {
        if (!this.skeleton || !this.currentAnim) {
            this.playAll(false, false);
            onComplete();
            return;
        }
        this.skeleton.setCompleteListener((entry) => {
            if (entry.trackIndex !== 0) return;
            this.skeleton.setCompleteListener(null!);
            onComplete();
        });
        this.playAll(false, false);
    }

    /**
     * 調整播放速度，供三段速（一般／快速／turbo）縮放演出時長用。
     *
     * @param scale 倍率，1 為原速。
     */
    public override setTimeScale(scale: number): void {
        if (this.skeleton) this.skeleton.timeScale = scale;
        for (const overlay of this.overlaySkeletons) {
            if (overlay) overlay.timeScale = scale;
        }
    }

    /**
     * 主 spine 與所有疊加 spine 一起從頭播。
     *
     * 動畫名是空字串時**不呼叫 `setAnimation`**：倍率球的靜止態就是「設好 skin 的 setup pose」，
     * 沒有對應的動畫可播，硬給一個名字只會讓 {@link trySetAnimation} 每次都警告一次。
     *
     * @param loop 主 spine 是否循環。
     * @param overlayLoop 疊加 spine 是否循環。
     */
    protected playAll(loop: boolean, overlayLoop: boolean): void {
        const anim = this.currentAnim;
        if (this.skeleton && anim) {
            this.skeleton.timeScale = 1;
            trySetAnimation(this.skeleton, anim, loop, 'SymbolViewSpine.playAll');
        }
        if (!this.overlayAnimName) return;
        for (const overlay of this.overlaySkeletons) {
            if (!overlay) continue;
            overlay.timeScale = 1;
            trySetAnimation(overlay, this.overlayAnimName, overlayLoop, 'SymbolViewSpine.playAll(overlay)');
        }
    }
}
