import { _decorator, Component, instantiate, Node, Prefab } from 'cc';
import { SymbolImageSet } from './SymbolImageSet';
import { SymbolState } from './SymbolState';
import { SymbolView } from './SymbolView';

const { ccclass, property } = _decorator;

/** 建池時要走過的狀態清單。新增狀態時這裡與 {@link SymbolImageSet.getTemplate} 要一起加 */
const POOLED_STATES: readonly SymbolState[] = [
    SymbolState.Normal,
    SymbolState.Blur,
    SymbolState.Tenpai,
    SymbolState.Black,
    SymbolState.WinAnimation,
    SymbolState.Erase,
    SymbolState.Idle,
];

/** 一個模板對應一個池。多個狀態 fallback 到同一份模板時共用同一個池 */
interface SymbolPool {
    /** 模板節點上的顯示層元件，`instantiate` 的來源 */
    readonly template: SymbolView;
    /** 目前閒置、可以直接拿出去用的物件 */
    readonly idle: SymbolView[];
}

/**
 * Symbol 顯示物件的物件池管理器。
 *
 * 設計依據：entry repo `docs/SlotSymbolSystem_設計參考.md` §5.3。
 *
 * 啟動時把每支 symbol prefab instantiate 一次當「模板庫」（放在一個關掉的節點底下，不會被看到、
 * 也不會被更新），之後所有顯示物件都是從模板複製出來的。格子換圖時走 {@link rent}／{@link returnView}，
 * 不再 `instantiate`／`destroy`。
 *
 * **為什麼池要以「符號 × 狀態」為鍵，而不是只以符號為鍵**：只以符號為鍵的話，租出去的是整顆
 * 含全部狀態子節點的實例，每個池又各自累積到自己的尖峰用量，節點總數反而比不用池還多。帶上狀態
 * 之後，同時存在的顯示物件數約等於使用中的格子數——一般狀態租到的是只有 Sprite 的輕量物件，
 * 只有中獎中的那幾格才會租到帶 Skeleton 的重物件。
 */
@ccclass('1001/SymbolImageManager')
export class SymbolImageManager extends Component {
    @property({
        type: [Prefab],
        tooltip: '每個符號一支 prefab（根節點掛 SymbolImageSet）。用 Prefab 參照而不是路徑字串，資產相依圖才抓得到'
    })
    public symbolPrefabs: Prefab[] = [];

    /** 依模板 uuid 查池，歸還時用 */
    private readonly poolsByUuid = new Map<string, SymbolPool>();

    /** 依 `symbolId × 1000 + state` 查池，租借時用 */
    private readonly poolsByKey = new Map<number, SymbolPool>();

    /** 模板庫的容器，整個關起來——模板本身永遠不顯示也不更新 */
    private templateRoot: Node = null!;

    /** 閒置物件的容器，同樣關起來 */
    private idleRoot: Node = null!;

    /** 已經警告過的 key，避免每幀重複洗版 */
    private readonly warnedKeys = new Set<number>();

    private ready = false;

    /**
     * 建立容器、展開所有 symbol prefab 並建池。
     *
     * 重複呼叫是安全的（第二次直接 return），方便讓 View 與 Task 都能在自己的初始化路徑上確保
     * 池子已經就緒，不必約定誰先誰後。
     */
    public init(): void {
        if (this.ready) return;
        this.ready = true;

        this.templateRoot = new Node('SymbolTemplates');
        this.templateRoot.setParent(this.node);
        this.templateRoot.active = false;

        this.idleRoot = new Node('SymbolIdle');
        this.idleRoot.setParent(this.node);
        this.idleRoot.active = false;

        for (const prefab of this.symbolPrefabs) {
            if (!prefab) continue;
            this.registerPrefab(prefab);
        }
    }

    /**
     * 展開一支 symbol prefab 成模板，並依 fallback 規則替它的每個狀態建池。
     *
     * @param prefab 根節點掛有 {@link SymbolImageSet} 的 prefab。
     */
    private registerPrefab(prefab: Prefab): void {
        const root = instantiate(prefab);
        root.setParent(this.templateRoot);

        const set = root.getComponent(SymbolImageSet);
        if (!set) {
            console.warn(`[SymbolImageManager] ${prefab.name} 的根節點沒有 SymbolImageSet，略過`);
            return;
        }
        if (!set.normal) {
            console.warn(`[SymbolImageManager] ${prefab.name}（id=${set.symbolId}）沒有填 normal，這個符號不會有任何畫面`);
            return;
        }

        // fallback 規則見規格書 §5.3。Tenpai 頂替的是 winAnimation 而不是 normal——
        // 聽牌與中獎的視覺語意都是「放大強調」，退回 normal 等於玩家看不出有聽牌（1001 不用這個狀態，
        // 規則照留是為了跟 1003 那份保持一致）。Idle 缺項時退回 normal：沒有落定演出的符號，
        // 落定之後本來就該維持靜態圖。
        const defaultNormal = set.normal;
        const defaultWin = set.winAnimation ?? defaultNormal;

        for (const state of POOLED_STATES) {
            const declared = set.getTemplate(state);
            const template = declared ?? (state === SymbolState.Tenpai ? defaultWin : defaultNormal);
            this.addPool(set.symbolId, state, template);
        }
    }

    /**
     * 把一個「符號 × 狀態」登記到某份模板的池上。
     *
     * @param symbolId 符號 id。
     * @param state 狀態。
     * @param template 這個組合要用的模板。
     */
    private addPool(symbolId: number, state: SymbolState, template: SymbolView): void {
        const uuid = template.node.uuid;
        let pool = this.poolsByUuid.get(uuid);
        if (!pool) {
            pool = { template, idle: [] };
            this.poolsByUuid.set(uuid, pool);
        }
        this.poolsByKey.set(SymbolImageManager.poolKey(symbolId, state), pool);
    }

    /**
     * 池的查找鍵。
     *
     * @param symbolId 符號 id。
     * @param state 狀態（bit flag 的整數值）。
     * @returns 查找鍵。
     */
    private static poolKey(symbolId: number, state: SymbolState): number {
        return symbolId * 1000 + state;
    }

    /**
     * 目前這顆顯示物件是不是已經來自正確的池。
     *
     * 給格子換狀態時判斷用：是的話只要重播動畫就好，不必歸還再租一顆。
     *
     * @param view 目前掛著的顯示物件。
     * @param symbolId 想要的符號 id。
     * @param state 想要的狀態。
     * @returns 兩者指向同一個池時為 true。
     */
    public isSame(view: SymbolView | null, symbolId: number, state: SymbolState): boolean {
        if (!view) return false;
        const pool = this.poolsByKey.get(SymbolImageManager.poolKey(symbolId, state));
        return !!pool && pool.template.node.uuid === view.poolKey;
    }

    /**
     * 租一顆顯示物件。池裡有閒置的就拿，沒有才從模板複製一顆。
     *
     * @param symbolId 符號 id。
     * @param state 狀態。
     * @returns 已啟用的顯示物件；沒有登記過這個組合時為 null（會警告一次）。
     */
    public rent(symbolId: number, state: SymbolState): SymbolView | null {
        if (!this.ready) this.init();

        const key = SymbolImageManager.poolKey(symbolId, state);
        const pool = this.poolsByKey.get(key);
        if (!pool) {
            if (!this.warnedKeys.has(key)) {
                this.warnedKeys.add(key);
                console.warn(`[SymbolImageManager] 沒有 symbolId=${symbolId} state=${state} 的池，該格不會顯示`);
            }
            return null;
        }

        let view = pool.idle.pop();
        if (!view) {
            const node = instantiate(pool.template.node);
            view = node.getComponent(SymbolView)!;
            view.poolKey = pool.template.node.uuid;
            view.initImage();
        }

        view.state = state;
        view.onRent(symbolId);
        return view;
    }

    /**
     * 歸還一顆顯示物件。節點不會被銷毀，只是關掉並移回閒置容器。
     *
     * @param view 要歸還的物件；傳 null 是安全的。
     */
    public returnView(view: SymbolView | null): void {
        if (!view?.isValid) return;

        view.onReturn();
        view.node.setParent(this.idleRoot);

        const pool = this.poolsByUuid.get(view.poolKey);
        if (!pool) {
            // 找不到池只可能是 poolKey 被外部改掉，節點留在 idleRoot 底下比銷毀安全
            console.warn(`[SymbolImageManager] 歸還時找不到 poolKey=${view.poolKey} 的池`);
            return;
        }
        pool.idle.push(view);
    }
}
